def strings(value):
 if isinstance(value,str):yield value
 elif isinstance(value,dict):
  for x in value.values():yield from strings(x)
 elif isinstance(value,list):
  for x in value:yield from strings(x)
def tools_of(body):
 def walk(tools,namespace=None):
  for t in tools:
   if t.get('type')=='namespace':yield from walk(t.get('tools',[]),t.get('name'))
   else:yield {**t,'namespace':namespace}
 tools=list(body.get('tools',[]))
 for item in body.get('input',[]):
  if item.get('type')=='additional_tools':tools.extend(item.get('tools',[]))
 return list(walk(tools))
def event(kind,**value):return 'event: '+kind+'\ndata: '+json.dumps({'type':kind,**value})+'\n\n'
def message(text):return {'id':'msg_'+str(time.time_ns()),'type':'message','role':'assistant','status':'completed','content':[{'type':'output_text','text':text,'annotations':[]}]}
def function(tool,args,label):return {'id':'fc_'+label,'type':'function_call','call_id':'call_'+label,'name':tool['name'],'namespace':tool['namespace'],'arguments':json.dumps(args)}
class Backend(http.server.BaseHTTPRequestHandler):
 def log_message(self,*args):pass
 def do_GET(self):requests.append({'method':'GET','path':self.path});self.send_response(404);self.end_headers()
 def do_POST(self):
  body=json.loads(self.rfile.read(int(self.headers['Content-Length'])));child=body.get('client_metadata',{}).get('x-openai-subagent')=='collab_spawn'
  requests.append({'method':'POST','path':self.path,'model':body.get('model'),'child':child,'body':body})
  try:
   if child:item=message('FIXTURE_CHILD_DONE')
   else:
    state['parent_calls']+=1;tools=tools_of(body)
    if state['parent_calls']==1:
     tool=next(t for t in tools if t.get('name')=='spawn_agent');assert 'agent_type' in tool['parameters']['properties']
     args={'task_name':'fixture_child','message':'Return only the fixed fixture completion. Do not call shell, edit, network or other tools.','agent_type':role,'fork_turns':'none'}
     state['spawn_args']=args;item=function(tool,args,'spawn')
    elif state['parent_calls']==2:
     tool=next(t for t in tools if t.get('name')=='wait_agent');item=function(tool,{'timeout_ms':10000},'wait')
    else:item=message('FIXTURE_PARENT_DONE')
   identifier='resp_'+str(time.time_ns());response={'id':identifier,'object':'response','status':'completed','output':[item],'usage':{'input_tokens':1,'output_tokens':1,'total_tokens':2}}
   raw=(event('response.created',response={**response,'status':'in_progress','output':[]})+event('response.output_item.added',output_index=0,item=item)+event('response.output_item.done',output_index=0,item=item)+event('response.completed',response=response)).encode()
   self.send_response(200);self.send_header('Content-Type','text/event-stream');self.send_header('Content-Length',str(len(raw)));self.end_headers();self.wfile.write(raw)
  except Exception as exc:
   state['errors'].append(repr(exc));raw=json.dumps({'error':repr(exc)}).encode();self.send_response(500);self.send_header('Content-Length',str(len(raw)));self.end_headers();self.wfile.write(raw)
