  api.TerminateJobObject(job,0);acc=Accounting();supervisor.checked(api.QueryInformationJobObject(job,1,ct.byref(acc),ct.sizeof(acc),None),ct);api.CloseHandle(job)
 return {'exit':p.returncode,'timeout':timed_out,'seconds':time.monotonic()-started,'job_active_final':acc.active,'stdout':stdout.decode('utf-8',errors='replace'),'stderr':stderr.decode('utf-8',errors='replace')}
def tree_hash(path):return {p.relative_to(path).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in path.rglob('*') if p.is_file()}
