 profiles=project/'.codex/model-projections';profiles.mkdir(parents=True);projection=profiles/(role+'.toml');binding=project/'.codex/config.toml'
 for case,bind,wrong in [('baseline',False,False),('projected',True,False),('withdrawn',False,False),('wrong_identity',True,True)]:
